//! Rewrites SupCom `#` comments to Lua `--` comments.
//!
//! SupCom runs Lua 5.0, which has no `#` length operator; its lexer treats `#`
//! (outside strings/comments) as the start of a line comment, both at line
//! start (`# autogenerated …` headers, `strings_db.lua` notes) and after code
//! (`opID = 'X1CA_001'  # should always be …` in campaign scripts). Luau reads
//! `#` as the length operator, so every such `#` becomes `--` and the rest of
//! the line is copied verbatim (a quote inside the comment must not open a
//! string).
//!
//! Game Lua never uses `#` as a length operator (FAF uses `table.getn`); only
//! FAF's editor/CI tooling scripts do, and the game never runs those. Engine
//! shims written in Luau are loaded directly and never pass through here.
//!
//! A `#` inside a string or comment is never rewritten — string/comment spans
//! are skipped wholesale via the shared [`super::lexscan`] scanners.

use super::lexscan::{long_bracket_level, skip_comment, skip_long_bracket, skip_qstring};

pub fn rewrite(source: &str) -> String {
    let b = source.as_bytes();
    // Nothing to do if there is no `#` at all (the overwhelmingly common case).
    if !b.contains(&b'#') {
        return source.to_owned();
    }

    // Work on bytes and reassemble at the end: the input is valid UTF-8 and we
    // only ever insert ASCII (`--`), so the result is valid UTF-8 too.
    let mut out: Vec<u8> = Vec::with_capacity(b.len() + 16);
    let mut i = 0;

    while i < b.len() {
        match b[i] {
            b'"' | b'\'' => {
                let end = skip_qstring(b, i);
                out.extend_from_slice(&b[i..end]);
                i = end;
            }
            b'[' => {
                let lvl = long_bracket_level(b, i);
                if lvl >= 0 {
                    let end = skip_long_bracket(b, i, lvl as usize);
                    out.extend_from_slice(&b[i..end]);
                    i = end;
                } else {
                    out.push(b'[');
                    i += 1;
                }
            }
            b'-' if b.get(i + 1) == Some(&b'-') => {
                let end = skip_comment(b, i);
                out.extend_from_slice(&b[i..end]);
                i = end;
            }
            b'#' => {
                // The rest of the line is comment text: copy it verbatim so a
                // quote inside it (e.g. `# Gari's Revenge`) isn't lexed as a string.
                out.extend_from_slice(b"--");
                let end = b[i..].iter().position(|&c| c == b'\n').map_or(b.len(), |p| i + p);
                out.extend_from_slice(&b[i + 1..end]);
                i = end;
            }
            c => {
                out.push(c);
                i += 1;
            }
        }
    }

    String::from_utf8(out).expect("hash_comment only inserts ASCII into valid UTF-8")
}

#[cfg(test)]
mod tests {

    #[test]
    fn quote_inside_hash_comment_does_not_open_a_string() {
        let src = "# Gari\\'s Revenge #1\r\nX = 1\r\n# next\r\nY = 2";
        assert_eq!(rewrite(src), "-- Gari\\'s Revenge #1\r\nX = 1\r\n-- next\r\nY = 2");
    }

    use super::*;

    #[test]
    fn leading_hash_line() {
        assert_eq!(rewrite("# header\nlocal x = 1"), "-- header\nlocal x = 1");
    }

    #[test]
    fn multiple_leading_hash_lines() {
        assert_eq!(
            rewrite("# autogenerated\n# do not edit\nlocal x = 1"),
            "-- autogenerated\n-- do not edit\nlocal x = 1"
        );
    }

    #[test]
    fn indented_hash_line() {
        assert_eq!(rewrite("\t  # indented note\n"), "\t  -- indented note\n");
    }

    #[test]
    fn mid_file_hash_line() {
        // The real `strings_db.lua` case: a `#` note between statements.
        let input = "FOO = \"a\"\n# part added later\nBAR = \"b\"";
        assert_eq!(rewrite(input), "FOO = \"a\"\n-- part added later\nBAR = \"b\"");
    }

    #[test]
    fn crlf_line_endings() {
        assert_eq!(rewrite("# a\r\n# b\r\nx = 1"), "-- a\r\n-- b\r\nx = 1");
    }

    #[test]
    fn shebang_first_line() {
        assert_eq!(rewrite("#!/usr/bin/lua\nlocal x = 1"), "--!/usr/bin/lua\nlocal x = 1");
    }

    #[test]
    fn hash_is_never_a_length_operator() {
        // Lua 5.0 has no `#` operator: it always starts a comment.
        assert_eq!(rewrite("local n = #t"), "local n = --t");
    }

    #[test]
    fn hash_inside_string_untouched() {
        assert_eq!(rewrite(r##"local s = "# not a comment""##), r##"local s = "# not a comment""##);
    }

    #[test]
    fn hash_at_line_start_inside_long_string_untouched() {
        let input = "local s = [[\n# inside string\n]]\n# real comment";
        assert_eq!(rewrite(input), "local s = [[\n# inside string\n]]\n-- real comment");
    }

    #[test]
    fn hash_inside_block_comment_untouched() {
        let input = "--[[\n# inside comment\n]]\nlocal x = 1";
        assert_eq!(rewrite(input), input);
    }

    #[test]
    fn no_hash_returns_unchanged() {
        let input = "local x = a + b\nlocal y = c";
        assert_eq!(rewrite(input), input);
    }

    #[test]
    fn trailing_hash_comment_after_code() {
        // From the FA campaign scripts (x1ca_001_operation.lua).
        assert_eq!(
            rewrite("opID = 'X1CA_001'\t\t# it's 'SCCA_' + faction\r\nY = 2"),
            "opID = 'X1CA_001'\t\t-- it's 'SCCA_' + faction\r\nY = 2"
        );
    }
}
